css:
#header-html,
#footer-html,
.print-heading,
.print-format .page-header,
.print-format .page-footer,
.page-header,
.page-footer,
#page-header,
#page-footer {
  display: none !important;
}

.print-format {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #1f2937;
  font-size: 11px;
}

.print-format * {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.report-meta {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #64748b;
  margin-bottom: 6px;
}

.report-header {
  text-align: center;
  border-bottom: 2px solid #1f2937;
  padding-bottom: 8px;
  margin-bottom: 12px;
}

.report-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.report-subtitle {
  font-size: 10px;
  color: #64748b;
  margin-top: 2px;
}

.section-title {
  font-weight: 600;
  font-size: 11px;
  margin: 12px 0 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}

.section-body {
  font-size: 11px;
  color: #334155;
  padding: 2px 0 6px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.info-grid.two-columns {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 8px;
}

.info-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.info-card table {
  width: 100%;
  border-collapse: collapse;
}

.info-card td {
  padding: 2px 0;
  vertical-align: top;
}

.info-card .label {
  width: 40%;
  color: #64748b;
}

.info-card .value {
  text-align: right;
  font-weight: 600;
  color: #111827;
}

.inspection-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.inspection-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.inspection-title {
  font-weight: 600;
  margin-bottom: 6px;
  color: #0f172a;
}

.inspection-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.inspection-list li {
  padding: 2px 0;
}

.inspection-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.inspection-note {
  font-size: 10px;
  color: #64748b;
  padding-left: 2px;
}

.status {
  font-weight: 600;
}

.status.ok {
  color: #059669;
}

.status.need-attention {
  color: #d97706;
}

.status.replace {
  color: #dc2626;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 8px;
}

.parts-list {
  margin: 0;
  padding-left: 16px;
  color: #334155;
}
